# frozen_string_literal: true

module SchemaMap
  # Renders the whole block body: a header line, a blank line, then one line per model.
  class Map
    def initialize(config)
      @config = config
    end

    def render
      models = ModelRegistry.new(@config).models
      lines = models.map { |model| ModelLine.new(model, @config, models).render }
      "#{header}\n\n#{lines.join("\n")}\n"
    end

    private

    def header
      "_Generated by `#{@config.command}` from Active Record reflection — do not edit by hand; " \
        "`#{@config.check_command}` fails when stale. Legend: `!` NOT NULL · `=v` default · " \
        "`a→b` through b · `x[as]` polymorphic has_* · `x*` polymorphic belongs_to · `x[]` has_many_attached._"
    end
  end
end
